def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    background = max(counts, key=counts.get)

    divider = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != background:
            divider = ("row", r, grid[r][0])
            break
    if divider is None:
        for c in range(w):
            color = grid[0][c]
            if color != background and all(grid[r][c] == color for r in range(h)):
                divider = ("col", c, color)
                break
    if divider is None:
        return [row[:] for row in grid]

    axis, pos, div_color = divider
    colors = [x for x in counts if x not in (background, div_color)]
    if not colors:
        return [row[:] for row in grid]
    obj_color = max(colors, key=lambda x: counts[x])
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == obj_color]
    out = [row[:] for row in grid]

    if axis == "row":
        top = min(r for r, c in points)
        bottom = max(r for r, c in points)
        if pos < top:
            shift = pos + 1 - top
            new_points = [(r + shift, c) for r, c in points]
            marker = max(r for r, c in new_points) + 1
        else:
            shift = pos - 1 - bottom
            new_points = [(r + shift, c) for r, c in points]
            marker = min(r for r, c in new_points) - 1
        for r, c in points:
            out[r][c] = background
        for r, c in new_points:
            out[r][c] = obj_color
        if 0 <= marker < h:
            out[marker] = [8] * w
    else:
        left = min(c for r, c in points)
        right = max(c for r, c in points)
        if pos < left:
            shift = pos + 1 - left
            new_points = [(r, c + shift) for r, c in points]
            marker = max(c for r, c in new_points) + 1
        else:
            shift = pos - 1 - right
            new_points = [(r, c + shift) for r, c in points]
            marker = min(c for r, c in new_points) - 1
        for r, c in points:
            out[r][c] = background
        for r, c in new_points:
            out[r][c] = obj_color
        if 0 <= marker < w:
            for r in range(h):
                out[r][marker] = 8
    return out
